const { deliver } = require('/workspace/src/dispatcher.js');

function mkIo(responses, opts = {}) {
  const calls = [];
  let i = 0;
  return {
    calls,
    io: {
      async post(url, body, options) {
        calls.push({ url, body, options });
        const r = responses[i++];
        if (typeof r === 'function') return r(calls.length);
        if (r instanceof Error) throw r;
        return r;
      },
      sleep(ms) { if (opts.trackSleep) calls.push({ sleep: ms }); return Promise.resolve(); },
    },
  };
}

(async () => {
  // 1. 502, 502, 200 with event id -> retries with idempotency key
  const t1 = mkIo([{ status: 502 }, { status: 502 }, { status: 200 }]);
  const r1 = await deliver(t1.io, { id: 'evt-1' });
  console.log('T1 result', r1.status, '| posts:', t1.calls.length);
  console.log('T1 headers:', JSON.stringify(t1.calls.map(c => c.options && c.options.headers)));

  // 2. 400 -> single attempt, no retry
  const t2 = mkIo([{ status: 400 }]);
  const r2 = await deliver(t2.io, { id: 'evt-2' });
  console.log('T2 result', r2.status, '| posts:', t2.calls.length);

  // 3. always 502 with key -> bounded at 5, returns last 502
  const t3 = mkIo(new Array(10).fill({ status: 502 }));
  const r3 = await deliver(t3.io, { id: 'evt-3' });
  console.log('T3 result', r3.status, '| posts:', t3.calls.length);

  // 4. 502 WITHOUT event id -> single attempt (historical double-charge guard)
  const t4 = mkIo([{ status: 502 }, { status: 200 }]);
  const r4 = await deliver(t4.io, { amount: 100 });
  console.log('T4 result', r4.status, '| posts:', t4.calls.length, '| headers:', JSON.stringify(t4.calls[0].options));

  // 5. transport error twice, then 200 -> retried, returns 200
  const err = new Error('ECONNRESET');
  const t5 = mkIo([err, err, { status: 200 }]);
  const r5 = await deliver(t5.io, { id: 'evt-5' });
  console.log('T5 result', r5.status, '| posts:', t5.calls.length);

  // 6. transport error 5 times -> bounded, throws last error
  const t6 = mkIo([err, err, err, err, err]);
  try { await deliver(t6.io, { id: 'evt-6' }); console.log('T6 FAIL: no throw'); }
  catch (e) { console.log('T6 threw:', e.message, '| posts:', t6.calls.length); }

  // 7. io without sleep -> still works
  const t7 = mkIo([{ status: 502 }, { status: 200 }]);
  delete t7.io.sleep;
  const r7 = await deliver(t7.io, { id: 'evt-7' });
  console.log('T7 result', r7.status, '| posts:', t7.calls.length);

  // 8. backoff increases
  const t8 = mkIo(new Array(5).fill({ status: 503 }), { trackSleep: true });
  await deliver(t8.io, { id: 'evt-8' });
  console.log('T8 sleeps:', JSON.stringify(t8.calls.filter(c => c.sleep).map(c => c.sleep)));
})().catch(e => { console.error('UNEXPECTED', e); process.exit(1); });
EOF

